```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: the time this heartbeat fired.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: one permitted fetch. A host outside the allowlist traps at
        // the boundary; a transport failure is a value and counts as zero chars.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notifier: report the heartbeat to the digest channel.
        let message = format!(
            "heartbeat at {seconds}: fetched {fetched} chars from {feed_url}"
        );
        let notified = notifier::notify(&message);

        // Contract: `ensures notified == true`. If the channel refused the
        // notification, no conforming output exists, so fail rather than emit
        // a report that violates the postcondition.
        if !notified {
            panic!("heartbeat notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

